'use strict';
const {upgrades,generators,boosts,stages,stageFlavors,goals}=LEMONADE_CONTENT;
let arcadeUnlocks={flappy:false,cookies:false,pop:false,rush:false};
let rebirths=0,zest=0,arcadeDodges=0,arcadeBest=0,cookiesCaught=0,lemonsPopped=0,ordersServed=0,deliveries=0,luckyLemons=0,festivalUntil=0,festivalReady=0,deliveryReady=0;
let clicks=0,total=0,basePower=1,baseRate=0,power=1,rate=0,clickMult=1,autoMult=1,taps=0,purchases=0,achievements=false,stage=0,toastTimer;
const $=id=>document.getElementById(id);
function setScene(index){const current=stages[index];const source='images/'+current.file;$('scene').src=source;$('scene').alt=current.name+' with a lemon emblem';$('scene-ambience').src=source;}
// Leave plenty of room below JavaScript's overflow boundary.
const MAX_CLICKS=1e100;
function finiteAmount(n){return typeof n!=='number'||Number.isNaN(n)?0:Math.max(0,Math.min(MAX_CLICKS,n));}
function addAmount(a,b){return finiteAmount(finiteAmount(a)+finiteAmount(b));}
function multiplyAmount(a,b){return finiteAmount(finiteAmount(a)*finiteAmount(b));}
function repairNumbers(){
clicks=finiteAmount(clicks);total=finiteAmount(total);taps=Math.min(Number.MAX_SAFE_INTEGER,Math.floor(finiteAmount(taps)));purchases=Math.min(Number.MAX_SAFE_INTEGER,Math.floor(finiteAmount(purchases)));
for(const item of [...upgrades,...generators,...boosts])item.owned=Math.min(boosts.includes(item)?1:Number.MAX_SAFE_INTEGER,Math.floor(finiteAmount(item.owned)));
basePower=upgrades.reduce((n,item)=>addAmount(n,multiplyAmount(item.gain,item.owned)),1);
baseRate=generators.reduce((n,item)=>addAmount(n,multiplyAmount(item.gain,item.owned)),0);
clickMult=boosts.reduce((n,item)=>item.owned?multiplyAmount(n,item.click):n,1);
autoMult=boosts.reduce((n,item)=>item.owned?multiplyAmount(n,item.auto):n,1);
clickMult=multiplyAmount(clickMult,1+zest*.25);autoMult=multiplyAmount(autoMult,1+zest*.25);const eventFactor=typeof festivalMultiplier==='function'?festivalMultiplier():1;power=multiplyAmount(multiplyAmount(basePower,clickMult),eventFactor);rate=multiplyAmount(multiplyAmount(baseRate,autoMult),eventFactor);
}
// Letter suffixes cover every supported balance, including the 1e100 cap.
const numberUnits=['','K','M','B','T','Qa','Qi','Sx','Sp','Oc','No','Dc','UDc','DDc','TDc','QaDc','QiDc','SxDc','SpDc','OcDc','NoDc','Vg','UVg','DVg','TVg','QaVg','QiVg','SxVg','SpVg','OcVg','NoVg','Tg','UTg','DTg'];
function fmt(n){
 n=finiteAmount(n);
 if(n<10000)return Math.floor(n).toLocaleString('en-US');
 let group=Math.min(numberUnits.length-1,Math.floor(Math.log10(n)/3));
 let scaled=n/Math.pow(1000,group);
 // Carry rounded values into the next suffix instead of showing 1,000M.
 if(scaled>=999.995&&group<numberUnits.length-1){group++;scaled=n/Math.pow(1000,group);}
 return scaled.toLocaleString('en-US',{maximumFractionDigits:2})+numberUnits[group];
}
const statsFmt=n=>{n=finiteAmount(n);return n<10000?n.toLocaleString('en-US',{maximumFractionDigits:1}):fmt(n);};
function cost(item){if(boosts.includes(item))return item.cost;const exponent=Math.floor(finiteAmount(item.owned));const price=item.cost*Math.pow(1.18,exponent);return Number.isFinite(price)&&price<=MAX_CLICKS?Math.ceil(price):null;}
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
function machineCount(){return generators.reduce((n,item)=>n+item.owned,0);}
function buildShop(){for(const [list,id] of [[upgrades,'upgrades'],[generators,'generators'],[boosts,'boosts']]){$(id).replaceChildren();list.forEach(item=>{item.owned=0;const row=document.createElement('div');row.className='item';row.innerHTML=`<span class="item-icon" aria-hidden="true">${item.icon}</span><div class="item-info"><div class="item-title">${item.name}<span class="owned">0 owned</span></div><div class="item-desc"></div></div><button class="buy"></button>`;item.button=row.querySelector('button');item.count=row.querySelector('.owned');item.description=row.querySelector('.item-desc');item.button.addEventListener('click',()=>buy(item,id));item.row=row;$(id).append(row);});}
$('achievement-list').replaceChildren();let lastSection='';goals.forEach(goal=>{goal.awarded=false;if(goal.section!==lastSection){const heading=document.createElement('h4');heading.className='goal-section';heading.textContent=goal.section;$('achievement-list').append(heading);lastSection=goal.section;}const row=document.createElement('div');row.className='goal';row.innerHTML=`<span class="goal-icon" aria-hidden="true">☆</span><div class="goal-info"><b>${goal.name}</b><p>${goal.desc}</p><div class="goal-track"><div></div></div></div><div class="goal-reward">+${fmt(goal.reward)}<small>bonus clicks</small></div>`;goal.row=row;goal.track=row.querySelector('.goal-track div');goal.icon=row.querySelector('.goal-icon');goal.title=row.querySelector('.goal-info b');goal.description=row.querySelector('.goal-info p');$('achievement-list').append(row);});}
function buy(item,type){if(window.cloudPaused)return;repairNumbers();if(boosts.includes(item)&&item.owned>=1)return;const price=cost(item);if(price===null||clicks<price)return;clicks=finiteAmount(clicks-price);item.owned++;purchases++;if(type==='upgrades')basePower+=item.gain;else if(type==='generators')baseRate+=item.gain;else{clickMult*=item.click;autoMult*=item.auto;}notify(`${item.name} purchased!`);update();}
function buyAchievements(){if(window.cloudPaused)return;repairNumbers();if(achievements||clicks<100)return;clicks-=100;achievements=true;purchases++;notify('Achievements unlocked! Complete goals for bonus clicks.');update();}
function values(){return {rebirths,dodges:arcadeDodges,caught:cookiesCaught,popped:lemonsPopped,served:ordersServed,deliveries,lucky:luckyLemons,taps,total,purchases,power,rate,machines:machineCount(),stage,boosts:boosts.reduce((n,b)=>n+b.owned,0),cookies:generators.find(item=>item.name==='Cookie counter').owned,upsells:upgrades.find(item=>item.name==='Upselling').owned};}
function checkAwards(){if(!achievements)return;const v=values();const awarded=[];for(const goal of goals){if(!goal.awarded&&stage>=(goal.minStage||0)&&v[goal.metric]>=goal.target){goal.awarded=true;clicks=addAmount(clicks,goal.reward);awarded.push(goal);}}if(awarded.length)notify(awarded.length===1?`${awarded[0].name}! +${fmt(awarded[0].reward)} bonus clicks`:`${awarded.length} achievements! +${fmt(awarded.reduce((n,g)=>n+g.reward,0))} bonus clicks`);}
function update(){repairNumbers();const previous=stage;stage=Math.max(0,Math.min(stages.length-1,Math.floor(finiteAmount(stage))));stage=Number.isInteger(window.devStageOverride)&&window.devStageOverride>=0&&window.devStageOverride<stages.length?window.devStageOverride:stages.reduce((n,s,i)=>clicks>=s.at?Math.max(n,i):n,stage);if(stage!==previous){setScene(stage);notify(`${stages[stage].name}! Your empire has expanded.`);}checkAwards();render();if(typeof renderFun==='function')renderFun();}
function sortShopRows(items,id){const sorted=[...items].sort((a,b)=>(cost(a)??Infinity)-(cost(b)??Infinity)||a.stageIndex-b.stageIndex);const children=$(id).children;if(sorted.some((item,i)=>children[i]!==item.row))$(id).append(...sorted.map(item=>item.row));}
function render(){$('balance').textContent=fmt(clicks);$('shop-balance').textContent=fmt(clicks);$('power').textContent=statsFmt(power);$('rate').textContent=statsFmt(rate);$('stage-name').textContent=stages[stage].name;$('shop-stage-label').textContent=stages[stage].name;$('stage-flavor').textContent=stageFlavors[stage];$('stage-count').textContent=`STAGE ${stage+1}`;$('rank').textContent=stages[stage+1]?'NEXT BUSINESS EXPANSION':'YOUR LEMONADE EMPIRE';const next=stages[stage+1];$('milestone-label').textContent=next?`${fmt(clicks)} / ${fmt(next.at)} banked`:`${fmt(clicks)} clicks in the bank`;$('progress').style.width=(next?Math.min(100,clicks/next.at*100):100)+'%';
for(const [items,type] of [[upgrades,'upgrades'],[generators,'generators'],[boosts,'boosts']])for(const item of items){item.row.hidden=false;const price=cost(item);const oneTime=boosts.includes(item);const bought=oneTime&&item.owned>=1;const maxed=price===null;item.button.textContent=bought?'Bought ✓':maxed?'Maxed':'Buy '+fmt(price);item.button.disabled=bought||maxed||clicks<price;item.button.setAttribute('aria-label',bought?`${item.name} already purchased`:maxed?`${item.name} has reached its purchase limit`:`Buy ${item.name} for ${fmt(price)} clicks${oneTime?', one-time purchase':''}`);item.count.textContent=oneTime?(bought?'Purchased':'One time'):item.owned+' owned';item.description.textContent=(item.flavor?item.flavor+' · ':'')+(type==='upgrades'?`+${statsFmt(multiplyAmount(item.gain,clickMult))} clicks per tap`:type==='generators'?`+${statsFmt(multiplyAmount(item.gain,autoMult))} clicks per second`:item.desc);}
for(const [items,id] of [[upgrades,'upgrades'],[generators,'generators'],[boosts,'boosts']])sortShopRows(items,id);
$('unlock-achievements').disabled=achievements||clicks<100;$('unlock-achievements').textContent=achievements?'Unlocked':'Buy · 100 ◈';$('achievement-help').textContent=achievements?'Completed goals pay bonus clicks automatically. Each reward is paid once.':'Buy Achievements to collect bonus clicks for taps, purchases, lemonade businesses, and cosmic milestones. Goals you already met count too.';
const v=values();let completed=0;for(const goal of goals){if(goal.awarded)completed++;goal.row.classList.toggle('completed',goal.awarded);goal.row.classList.toggle('locked',!achievements);goal.icon.textContent=goal.awarded?'✓':'☆';goal.track.style.width=(goal.awarded?100:stage<(goal.minStage||0)?0:Math.min(100,v[goal.metric]/goal.target*100))+'%';const secret=!goal.awarded&&stage<Math.max(goal.minStage||0,goal.metric==='stage'?goal.target:0);goal.title.textContent=secret?'Secret discovery':goal.name;goal.description.textContent=secret?'Discover a new business location to reveal this goal.':goal.desc;goal.row.setAttribute('aria-label',`${goal.title.textContent}: ${goal.description.textContent}. ${goal.awarded?'Completed':achievements?'In progress':'Locked'}. Reward ${goal.reward} clicks.`);}$('achievement-count').textContent=`${completed} / ${goals.length}`;}

function tap(){if(window.cloudPaused)return;repairNumbers();clicks=addAmount(clicks,power);total=addAmount(total,power);taps=Math.min(Number.MAX_SAFE_INTEGER,taps+1);const p=document.createElement('span');p.className='particle';p.textContent='+'+fmt(power);p.style.marginLeft=(Math.random()*90-45)+'px';$('particles').append(p);setTimeout(()=>p.remove(),800);update();}
function tick(elapsed){if(window.cloudPaused)return;repairNumbers();const seconds=Number.isFinite(elapsed)?Math.max(0,elapsed):0;const regular=multiplyAmount(baseRate,autoMult);const bonusSeconds=typeof festivalBonusSeconds==='function'?festivalBonusSeconds(seconds):0;const earned=multiplyAmount(regular,seconds+bonusSeconds);clicks=addAmount(clicks,earned);total=addAmount(total,earned);update();}
function reset(keepLegacy=false){window.devStageOverride=null;if(!keepLegacy&&typeof resetExtras==='function')resetExtras();clicks=total=baseRate=rate=taps=purchases=stage=0;basePower=power=clickMult=autoMult=1;achievements=false;buildShop();setScene(0);last=performance.now();update();}
$('click').addEventListener('click',tap);$('unlock-achievements').addEventListener('click',buyAchievements);
for(const tab of document.querySelectorAll('[role="tab"]'))tab.addEventListener('click',()=>{for(const t of document.querySelectorAll('[role="tab"]'))t.setAttribute('aria-selected',String(t===tab));for(const panel of document.querySelectorAll('[role="tabpanel"]'))panel.hidden=panel.id!==tab.getAttribute('aria-controls');});
$('restart').addEventListener('click',()=>$('reset-dialog').showModal());$('cancel-reset').addEventListener('click',()=>$('reset-dialog').close());$('confirm-reset').addEventListener('click',()=>{reset();$('reset-dialog').close();notify('A fresh lemonade stand. Make your first click!');});
let last=performance.now();setInterval(()=>{const now=performance.now();tick((now-last)/1000);last=now;},100);
// Load only the current scene; later destinations remain surprises.
buildShop();update();

function setShopOpen(open){$('shop').hidden=false;$('shop').inert=!open;$('shop').setAttribute('aria-hidden',String(!open));$('shop-toggle').setAttribute('aria-expanded',String(open));$('shop-toggle').setAttribute('aria-label',open?'Close upgrades sidebar':'Open upgrades sidebar');$('shop-arrow').textContent=open?'›':'‹';document.body.classList.toggle('shop-open',open);}
$('shop-toggle').addEventListener('click',()=>setShopOpen(!document.body.classList.contains('shop-open')));
$('shop-minimize').addEventListener('click',()=>{setShopOpen(false);$('shop-toggle').focus();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('shop-open')&&!document.querySelector('dialog[open]')){setShopOpen(false);$('shop-toggle').focus();}});
setShopOpen(false);
